INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66611248', 66611248, 'analyze_legacy', 'Kementerian Hukum', 'central', 'DIREKTORAT JENDERAL ADMINISTRASI HUKUM UMUM', 'Pengadaan Sewa bandwith Bimbingan Teknis Layanan Perseroan Perorangan pada Aplikasi AHU Link Pada Direktorat Badan Usaha Direktorat Jenderal Administrasi Hukum Umum Tahun Anggaran 2026', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 10000000, 'February 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', 'Pekerjaan sewa bandwidth ini bertujuan untuk mendukung kelancaran pelaksanaan Bimbingan Teknis (Bimtek) Layanan Perseroan Perorangan melalui aplikasi AHU Link secara daring dengan menyediakan koneksi internet yang stabil, cepat, dan andal. Penyedia jasa bertanggung jawab memastikan ketersediaan bandwidth yang memadai agar seluruh proses penyampaian materi, interaksi peserta, dan akses sistem dapat berlangsung tanpa gangguan, termasuk memberikan dukungan teknis selama kegiatan berlangsung.', 'Tersedianya layanan bandwidth dedicated dengan kapasitas yang memadai sesuai kebutuhan kegiatan, menjamin kualitas layanan dengan tingkat uptime tinggi, latensi rendah, serta minim gangguan, didukung oleh monitoring jaringan secara real-time dan dukungan teknis siaga. Layanan juga mencakup aspek keamanan jaringan, pelaporan kinerja, serta opsi koneksi cadangan untuk menjaga keberlangsungan layanan selama pelaksanaan Bimtek.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2881531);
