INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66620531', 66620531, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Konsultan Penyusunan Pengembangan Kerangka Kebijakan dan Tata Kelola Perencanaan Infrastruktur dan Anggaran Ilmu Pengetahuan dan Teknologi', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 100000000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. Melakukan koordinasi dengan kementerian/lembaga/unit teknis terkait untuk pengumpulan dan inventarisasi mengenai data pendukung kajian; 2. Melakukan penghimpunan, kompilasi, dan pengolahan data dan informasi (kuantitatif dan kualitatif) serta analisis komparasi dan pendalaman/studi literatur terhadap kondisi eksisting; 3. Melakukan pemetaan dan visualisasi data guna mendukung proses pencatatan, analisis, dan pelaporan kajian pengembangan kerangka kebijkana dan tata kelola perencanaan infrastruktur dan pendanaan iptekin; dan 4. Mendukung dan membantu pelaksanaan kegiatan teknis dan substantif lainnya yang menunjang tugas dan fungsi Direktorat Pendidikan Tinggi dan Iptek.', 'Bukan Aparatur Sipil Negara (ASN) baik Pegawai Negeri Sipil (PNS), Calon Pegawai Negeri Sipil (CPNS), maupun Pegawai Pemerintah dengan Perjanjian Kerja (PPPK); Pendidikan minimal S1 (bachelor degree) dari perguruan tinggi dalam negeri ataupun luar negeri dengan jurusan Sistem Informasi, Teknik Mesin, Teknik Elektro, Teknik Fisika, Biologi, Matematika atau jurusan lain yang relevan serta memiliki pengalaman penelitian dan penulisan laporan/kajian; Memiliki Nomor Induk Berusaha (NIB) Perorangan yang masih aktif dan diterbitkan melalui sistem Online Single Submission (OSS); Memiliki pengalaman kerja minimal 3 tahun; Indeks Prestasi Kumulatif (IPK) minimal 3,25 dari skala 4,00; Tertarik dengan isu-isu terkait Iptek dan Inovasi, diutamakan memiliki pengalaman dalam penelitian dan penulisan laporan/kajian; Memiliki kemampuan dalam penulisan ilmiah dan telah memiliki karya tulis ilmiah yang dipublikasikan (nasional dan/atau internasional); Bersedia bekerja mulai bulan April 2026 s.d. Desember 2026 di kantor Kementerian PPN/Bappenas; Mampu bekerja dengan baik, disiplin, dan sungguh-sungguh serta mempunyai komitmen dan motivasi untuk bekerja secara individu maupun bersama tim; dan Berkepribadian baik dan mampu berkomitmen untuk memberikan output terbaik.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2886704);
