INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66620326', 66620326, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Konsultan Penyusunan Peta Jalan Pendidikan Tinggi Vokasi untuk Penyiapan Lulusan Menuju Pasar Kerja Global', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 100000000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Melakukan penghimpunan, kompilasi, dan pengolahan data dan informasi (kuantitatif dan kualitatif) serta analisis komparasi dan pendalaman/studi literatur terhadap kajian isu pendidikan tinggi vokasi menggunakan pertimbangan pendekatan analisis data dan informasi berbasis bukti. Menghimpun dan menganalisis data pendidikan tinggi vokasi, termasuk sebaran PTV, program studi, bidang keahlian, dan profil lulusan. Menganalisis kebutuhan pasar kerja global, termasuk sektor prioritas, negara tujuan, standar kompetensi, dan sertifikasi internasional. Mengidentifikasi kesenjangan (gap analysis) antara kompetensi lulusan pendidikan tinggi vokasi Indonesia dan kebutuhan pasar kerja global. Menyusun rekomendasi kebijakan penguatan kurikulum, kemitraan industri global, sertifikasi, dan mobilitas lulusan pendidikan tinggi vokasi. Mengumpulkan informasi dan data dukung untuk kebutuhan penyusunan policy brief, analisis, dan materi presentasi pimpinan terkait penguatan pendidikan tinggi vokasi.', 'Bukan Aparatur Sipil Negara (ASN) baik Pegawai Negeri Sipil (PNS), Calon Pegawai Negeri Sipil (CPNS), maupun Pegawai Pemerintah dengan Perjanjian Kerja (PPPK); Pendidikan minimal S1 (bachelor degree) dari perguruan tinggi dalam negeri ataupun luar negeri dengan jurusan Kebijakan Publik, Sosial Humaniora, Ilmu Pendidikan, Ilmu Ekonomi, Statistika, atau jurusan lain yang relevan serta memiliki pengalaman penelitian dan penulisan laporan/kajian; Memiliki Nomor Induk Berusaha (NIB) Perorangan yang masih aktif dan diterbitkan melalui sistem Online Single Submission (OSS); Memiliki pengalaman kerja minimal 3 tahun; Indeks Prestasi Kumulatif (IPK) minimal 3,25 dari skala 4,00; Tertarik dengan isu-isu terkait Pendidikan Tinggi, khusunya keterkaitan dengan pendidikan tinggi vokasi dan pasar kerja global, diutamakan memiliki pengalaman dalam penelitian dan penulisan laporan/kajian; Memiliki kemampuan dalam penulisan ilmiah dan telah memiliki karya tulis ilmiah yang dipublikasikan (nasional dan/atau internasional); Bersedia bekerja mulai bulan April 2026 s.d. Desember 2026 di kantor Kementerian PPN/Bappenas; Mampu bekerja dengan baik, disiplin, dan sungguh-sungguh serta mempunyai komitmen dan motivasi untuk bekerja secara individu maupun bersama tim; Berkepribadian baik dan mampu bekerja sama; dan Berkomitmen untuk memberikan output terbaik sesuai dengan batas waktu yang ditetapkan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2887419);
